INSERT INTO `translations` (`id`, `locale`, `key`, `value`, `is_default`, `created_at`, `updated_at`) VALUES
(10966, 'br', 'BarcodeSymbologyTooltip', 'O formato de código de barras que corresponde à etiqueta do seu produto. CODE128 é o padrão seguro para a maioria dos produtos.', 0, '2026-07-07 00:40:37.000000', '2026-07-07 00:40:37.000000'),
(10967, 'br', 'ProductCodeTooltip', 'Um identificador único para este produto. Escaneie um código de barras existente ou clique no botão de código de barras para gerar um. Certifique-se de que a simbologia acima corresponda ao código.', 0, '2026-07-07 00:40:37.000000', '2026-07-07 00:40:37.000000'),
(10968, 'br', 'SubcategoriesMultiTooltip', 'Opcional. Escolha uma ou mais subcategorias que pertencem às categorias selecionadas. A primeira é salva como subcategoria principal para APIs e filtros legados.', 0, '2026-07-07 00:40:37.000000', '2026-07-07 00:40:37.000000'),
(10969, 'br', 'BrandTooltip', 'Opcional. O fabricante ou marca deste produto. Ajuda na filtragem, relatórios e navegação na loja.', 0, '2026-07-07 00:40:37.000000', '2026-07-07 00:40:37.000000'),
(10970, 'br', 'DescriptionTooltip', 'Opcional. Uma breve descrição exibida em recibos, faturas e sua loja online. Mantenha-a concisa e amigável ao cliente.', 0, '2026-07-07 00:40:37.000000', '2026-07-07 00:40:37.000000'),
(10971, 'br', 'EditProductDetailsHint', 'Revise e atualize as informações do produto, preços e estoque. As alterações são aplicadas após salvar.', 0, '2026-07-07 00:40:37.000000', '2026-07-07 00:40:37.000000'),
