(33636, 'hn', 'ProductNameTooltip', 'रसीदों, चालानों, आपके स्टोर और रिपोर्ट पर दिखाया गया नाम। 3 से 55 वर्ण।', 0, '2026-07-07 00:40:37.000000', '2026-07-07 00:40:37.000000'),
(33637, 'hn', 'BarcodeSymbologyTooltip', 'बारकोड प्रारूप जो आपके उत्पाद लेबल से मेल खाता है। CODE128 अधिकांश उत्पादों के लिए सुरक्षित डिफ़ॉल्ट है।', 0, '2026-07-07 00:40:37.000000', '2026-07-07 00:40:37.000000'),
(33638, 'hn', 'ProductCodeTooltip', 'इस उत्पाद के लिए एक अद्वितीय पहचानकर्ता। मौजूदा बारकोड स्कैन करें या एक उत्पन्न करने के लिए बारकोड बटन पर क्लिक करें। सुनिश्चित करें कि ऊपर दी गई सिम्बोलॉजी कोड से मेल खाती है।', 0, '2026-07-07 00:40:37.000000', '2026-07-07 00:40:37.000000'),
(33639, 'hn', 'SubcategoriesMultiTooltip', 'वैकल्पिक। चयनित श्रेणियों से संबंधित एक या अधिक उपश्रेणियाँ चुनें। पहली पुराने API और फ़िल्टर के लिए प्राथमिक उपश्रेणी के रूप में सहेजी जाती है।', 0, '2026-07-07 00:40:37.000000', '2026-07-07 00:40:37.000000'),
(33640, 'hn', 'BrandTooltip', 'वैकल्पिक। इस उत्पाद का निर्माता या ब्रांड। फ़िल्टरिंग, रिपोर्टिंग और स्टोरफ्रंट ब्राउज़िंग में मदद करता है।', 0, '2026-07-07 00:40:37.000000', '2026-07-07 00:40:37.000000'),
(33641, 'hn', 'DescriptionTooltip', 'वैकल्पिक। रसीदों, चालानों और आपके ऑनलाइन स्टोर पर दिखाया गया एक संक्षिप्त विवरण। इसे संक्षिप्त और ग्राहक के अनुकूल रखें।', 0, '2026-07-07 00:40:37.000000', '2026-07-07 00:40:37.000000'),
(33642, 'hn', 'EditProductDetailsHint', 'उत्पाद जानकारी, मूल्य निर्धारण और स्टॉक की समीक्षा करें और अपडेट करें। सहेजने के बाद परिवर्तन लागू होते हैं।', 0, '2026-07-07 00:40:37.000000', '2026-07-07 00:40:37.000000'),
