(1, 'Invoice Created', 'invoice_created', 'Hello {{customer_name}}, your invoice {{invoice_number}} from {{company_name}} for {{total_amount}} has been created. Thank you!', 'en', NULL, 1, '2026-07-07 00:40:37', '2026-07-07 00:40:37', NULL),
(2, 'Payment Received', 'payment_received', 'Hi {{customer_name}}, we received your payment of {{total_amount}} for {{invoice_number}}. Status: {{payment_status}}. Thank you for your business with {{company_name}}.', 'en', NULL, 1, '2026-07-07 00:40:37', '2026-07-07 00:40:37', NULL),
(3, 'Order Confirmation', 'order_created', 'Hello {{customer_name}}, your order {{invoice_number}} with {{company_name}} has been confirmed. Total: {{total_amount}}.', 'en', NULL, 1, '2026-07-07 00:40:37', '2026-07-07 00:40:37', NULL),
(4, 'Order Status Update', 'order_status', 'Hi {{customer_name}}, the status of your order {{invoice_number}} is now: {{order_status}}.', 'en', NULL, 1, '2026-07-07 00:40:37', '2026-07-07 00:40:37', NULL);
